@js:
(function () {
  var items = []
  var mode = qmExploreMode.call(this)
  function section(title) { items.push({title:title,url:null,style:{layout_flexGrow:1,layout_flexBasisPercent:1}}) }
  function add(title, rank, tab) { items.push({title:title,url:'@js:\nqmExploreUrl(' + JSON.stringify(rank) + ',' + JSON.stringify(tab) + ')',style:{layout_flexGrow:1,layout_flexBasisPercent:0.31}}) }
  function addList(title, kind, id, gender) { items.push({title:title,url:'@js:\nqmExploreListUrl(' + JSON.stringify(kind) + ',' + JSON.stringify(id) + ',' + JSON.stringify(gender || '2') + ',page)',style:{layout_flexGrow:1,layout_flexBasisPercent:0.24}}) }
  function addHome(title, kind) { items.push({title:title,url:'@js:\nqmExploreHomeUrl.call(this,' + JSON.stringify(mode) + ',page,' + JSON.stringify(kind || '') + ')',style:{layout_flexGrow:1,layout_flexBasisPercent:0.31}}) }
  function addMedia(title, keyword) { items.push({title:title,url:'@js:\nqmExploreMediaSearchUrl.call(this,' + JSON.stringify(mode) + ',' + JSON.stringify(keyword) + ',page)',style:{layout_flexGrow:1,layout_flexBasisPercent:0.31}}) }
  if (mode == 'novel') {
    section('男频榜单')
    add('推荐榜','rec_list','1'); add('大热榜','hot_list','1'); add('新书榜','new_list','1')
    add('完结榜','end_list','1'); add('飙升榜','up_list','1'); add('好评榜','good_comment_list','1')
    add('热搜榜','hot_search_list','1'); add('必读榜','must_read_list','1'); add('礼物榜','reward_value_list','1')
    section('女频榜单')
    add('推荐榜','rec_list','2'); add('大热榜','hot_list','2'); add('新书榜','new_list','2')
    add('完结榜','end_list','2'); add('飙升榜','up_list','2'); add('好评榜','good_comment_list','2')
    add('热搜榜','hot_search_list','2'); add('必读榜','must_read_list','2'); add('礼物榜','reward_value_list','2')
    section('分类与标签')
    addList('现代言情','category','1','2'); addList('古代言情','category','2','2'); addList('幻想言情','category','4','2'); addList('玄幻奇幻','category','202','2')
    addList('都市人生','category','203','2'); addList('武侠仙侠','category','205','2'); addList('历史','category','56','2'); addList('科幻','category','64','2')
    addList('种田','tag','317','2'); addList('快穿','tag','335','2'); addList('脑洞','tag','526','2'); addList('系统','tag','782','2')
  } else if (mode == 'publish') {
    section('出版图书')
    addHome('图书精选','')
    addList('文学艺术','category','240','2'); addList('人文社科','category','241','2'); addList('人物传记','category','247','2'); addList('经典文学','category','243','2')
    addList('经管励志','category','242','2'); addList('出版小说','category','257','2'); addList('少儿教育','category','258','2'); addList('青春文学','category','265','2')
    addList('科幻未来','category','261','2'); addList('悬疑推理','category','262','2'); addList('仙侠玄幻','category','288','2'); addList('历史小说','category','264','2')
  } else if (mode == 'audio') {
    section('听书首页')
    addHome('听书精选',''); addMedia('热门听书','都市'); addMedia('经典听书','经典'); addMedia('有声小说','小说')
  } else {
    section('短剧 / 漫剧视频')
    addHome('热门短剧','drama'); addHome('热门漫剧','animated')
    addMedia('都市视频','都市'); addMedia('古装视频','古装'); addMedia('悬疑视频','悬疑')
  }
  return JSON.stringify(items)
})()

